import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportExportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom "sanitizer" that only blocks obvious attacks
    private String sanitizeInput(String input) {
        if (input == null) return null;
        // Remove comments and semicolons
        input = input.replaceAll("--", "");
        input = input.replaceAll(";", "");
        input = input.replaceAll("/\\*.*?\\*/", "");
        return input.trim();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String department = req.getParameter("dept");

        // Validate report type against whitelist
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation
        if (!isValidDate(dateFrom) || !isValidDate(dateTo)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Apply our sanitizer to user inputs
        sortCol = sanitizeInput(sortCol);
        department = sanitizeInput(department);

        String query = buildQuery(reportType, dateFrom, dateTo, sortCol, department);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= cols; i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private String buildQuery(String type, String from, String to, 
                              String sort, String dept) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM reports_").append(type);
        sb.append(" WHERE created_at BETWEEN '").append(from);
        sb.append("' AND '").append(to).append("'");

        if (dept != null && !dept.isEmpty()) {
            sb.append(" AND department = '").append(dept).append("'");
        }

        if (sort != null && !sort.isEmpty()) {
            sb.append(" ORDER BY ").append(sort);
        }

        return sb.toString();
    }

    private boolean isValidReportType(String type) {
        return type != null && type.matches("^(sales|inventory|hr|finance)$");
    }

    private boolean isValidDate(String date) {
        return date != null && date.matches("^\\d{4}-\\d{2}-\\d{2}$");
    }
}
